function updateCountLabels(){const total=(eastSystem==='tv'?eastCount:0)+(northProjection?0:northCount)+2+(westExtra.visible?1:0);$('tvTotal').textContent=total+' TVs in this layout';$('northDisplay').parentElement.hidden=!MAD;$('northDisplay').value=northProjection?'projection':'tv';$('northCount').parentElement.hidden=northProjection;document.getElementById('tvCountTitle').textContent=eastSystem==='led'?(ledCols*ledRows)+' LED cabinets / long wall':eastCount+' × 75-inch / long wall';$('eastCount').parentElement.hidden=eastSystem==='led';$('ledSettings').hidden=eastSystem!=='led';$('eastSystem').value=eastSystem;document.querySelector('[data-view="north"]').textContent=northProjection?'Entrance projection':'Entrance wall · '+northCount+' TVs';document.getElementById('entranceCountNote').textContent=northProjection?'Two 16:9 projected images beside the entrance.':northCount+' portrait 75-inch TVs beside entrance.';if(eastSystem==='led')$('screenFacts').innerHTML='LED active area: '+lengthText(ledW())+' × '+lengthText(ledH())+'<br>'+(ledCols*ledRows)+' cabinets / '+ledCols+' × '+ledRows+'<br>Sill: '+lengthText(.9)+' · Top: '+lengthText(.9+ledH())+'<br>Ceiling: '+lengthText(3.4)+(MAD?' assumed':' confirmed')+'';$('countReadout').textContent='Long wall: '+lengthText(eastWidth())+' framed; '+lengthText((ROOM_L-eastWidth())/2)+' at each end. Entrance: '+lengthText(northWidth())+(northProjection?' projected at '+lengthText(ph)+' high, centred':' framed, centred')+' in the estimated '+lengthText(entranceRight-entranceLeft)+' section beside the door.';}
function decorateGenerated(g){g.traverse(o=>{if(o.userData.ledGrid)o.visible=mode==='cad';if(o.isMesh){o.userData.originalMaterial=o.material;const edge=new T.LineSegments(new T.EdgesGeometry(o.geometry),edgeMat);edge.userData.cad=true;edge.visible=mode==='cad';o.add(edge);if(mode==='cad')o.material=cadMat}})}
$('eastCount').value=eastCount;$('northCount').value=northCount;
for(const id of ['eastCount','northCount'])$(id).onchange=()=>{const max=id==='eastCount'?12:3;const n=Math.max(0,Math.min(max,Math.round(+$(id).value)||0));$(id).value=n;if(id==='eastCount'){eastCount=n;buildEast();decorateGenerated(eastScreens);decorateGenerated(eastWall)}else{northCount=n;buildNorth();decorateGenerated(northScreens);decorateGenerated(northWall)}clearMeasurement();try{storage.setItem('snug-tv-counts',JSON.stringify({east:eastCount,north:northCount}))}catch{}updateCountLabels();updateUnits(units);};updateCountLabels();
$('northDisplay').onchange=()=>{northProjection=MAD&&$('northDisplay').value==='projection';try{storage.setItem('snug-north-display',northProjection?'projection':'tv')}catch{}buildNorth();decorateGenerated(northScreens);decorateGenerated(northWall);clearMeasurement();updateCountLabels();refreshDimensions();if(cleanWiringState)refreshWiring();};
function rebuildEastSystem(){buildEast();decorateGenerated(eastScreens);decorateGenerated(eastWall);clearMeasurement();updateUnits(units)}
$('eastSystem').onchange=e=>{eastSystem=e.target.value;try{storage.setItem('snug-east-system',eastSystem)}catch{}rebuildEastSystem()};
function showLedResolution(){const w=ledPixelsW,h=ledPixelsH;$('ledResolution').textContent=w&&h?'Native canvas: '+(w*ledCols)+' × '+(h*ledRows)+' px. Cabinet: '+w+' × '+h+' px. Actual pitch from geometry: '+(cabinetW()*1000/w).toFixed(4)+' × '+(cabinetH()*1000/h).toFixed(4)+' mm.':'Exact content resolution pending supplier cabinet pixel dimensions.';}
$('cabinetPixelsW').value=ledPixelsW||'';$('cabinetPixelsH').value=ledPixelsH||'';
for(const id of ['cabinetPixelsW','cabinetPixelsH'])$(id).onchange=()=>{const parse=id=>{const v=+$(id).value;return Number.isInteger(v)&&v>0&&v<=4096?v:null};ledPixelsW=parse('cabinetPixelsW');ledPixelsH=parse('cabinetPixelsH');try{storage.setItem('snug-led-pixels',JSON.stringify({w:ledPixelsW,h:ledPixelsH}))}catch{}showLedResolution();};showLedResolution();
$('ledImage').onchange=e=>{const file=e.target.files[0];if(!file)return;const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{ledCustomTexture?.dispose();ledCustomTexture=new T.Texture(img);ledCustomTexture.colorSpace=T.SRGBColorSpace;ledCustomTexture.needsUpdate=true;const max=renderer.capabilities.maxTextureSize;let message='Image: '+img.width+' × '+img.height+' px. ';if(ledPixelsW&&ledPixelsH)message+=(img.width===ledPixelsW*ledCols&&img.height===ledPixelsH*ledRows?'Matches configured native canvas. ':'Does not match configured native canvas. ');else message+='Set cabinet pixels to check native match. ';if(img.width>max||img.height>max)message+='Preview exceeds GPU texture limit; browser may downsample. ';$('ledImageInfo').textContent=message+'Image selection is temporary for this session.';rebuildEastSystem();URL.revokeObjectURL(url)};img.onerror=()=>{URL.revokeObjectURL(url);$('ledImageInfo').textContent='Could not open this image.'};img.src=url};
function syncLedLayoutUI(){$('ledCols').max=Math.floor(ledMaxWidth/cabinetW());$('ledType').value=ledType;$('ledCols').value=ledCols;$('ledRows').value=ledRows;$('ledGeometry').textContent=ledCols+' × '+ledRows+' = '+(ledCols*ledRows)+' cabinets. Active area '+lengthText(ledW())+' × '+lengthText(ledH())+'. Cabinet '+(cabinetW()*1000)+' × '+(cabinetH()*1000)+' mm. '+(ledType==='600'?'Depth 39.75 mm.':'Depth not supplied; 50 mm placeholder in model.');$('eastSystem').options[0].textContent='LED · '+(ledCols*ledRows)+' cabinets';}
for(const id of ['ledType','ledCols','ledRows'])$(id).onchange=()=>{if(id==='ledType'){ledType=$('ledType').value;ledCols=ledType==='600'?14:16;ledRows=ledType==='600'?4:3;ledPixelsW=null;ledPixelsH=null;$('cabinetPixelsW').value='';$('cabinetPixelsH').value='';try{storage.removeItem('snug-led-pixels')}catch{}}else{ledCols=Math.max(1,Math.min(Math.floor(ledMaxWidth/cabinetW()),Math.round(+$('ledCols').value)||1));ledRows=Math.max(1,Math.min(Math.floor(2.46/cabinetH()),Math.round(+$('ledRows').value)||1))}syncLedLayoutUI();showLedResolution();rebuildEastSystem();try{storage.setItem('snug-led-layout-v2',JSON.stringify({type:ledType,cols:ledCols,rows:ledRows}))}catch{}};syncLedLayoutUI();
const cleanWiringGroup=new T.Group();scene.add(cleanWiringGroup);cleanWiringGroup.visible=false;
const wiringGroup=new T.Group(),hdmiGroup=new T.Group(),powerGroup=new T.Group();scene.add(wiringGroup);wiringGroup.add(hdmiGroup,powerGroup);hdmiGroup.visible=false;powerGroup.visible=false;
function wirePath(points,color,parent){const curve=new T.CurvePath();let length=0;for(let i=1;i<points.length;i++){if(points[i].distanceTo(points[i-1])<.00001)continue;curve.add(new T.LineCurve3(points[i-1],points[i]));length+=points[i].distanceTo(points[i-1]);}if(curve.curves.length){const cable=new T.Mesh(new T.TubeGeometry(curve,Math.max(12,points.length*8),parent===cleanWiringGroup?.008:.022,6,false),new T.MeshBasicMaterial({color,depthTest:parent===cleanWiringGroup}));cable.renderOrder=1001;parent.add(cable);}return length}
let equipmentStamp='';
function refreshWiring(){if(cleanWiringState){for(const o of scene.children)o.visible=o===wiringGroup||o===cleanWiringGroup||o===eastScreens||o===northScreens;drawCleanWiring();}clearGroup(hdmiGroup);clearGroup(powerGroup);scene.updateMatrixWorld(true);const pc=equipment.localToWorld(new T.Vector3(0,.55,.18)),supply=new T.Vector3(X-.08,3.15,0);let rows=[];
if(eastSystem==='tv'){for(let i=0;i<eastCount;i++){const z=(i-(eastCount-1)/2)*pitch;const gpu=i<4?'GPU A / '+(i+1):i<8?'GPU B / '+(i-3):'Output TBD';const upper=$('hdmiPath').value==='top',routeY=upper?3.02:.12;const route=[pc.clone(),new T.Vector3(pc.x,routeY,pc.z),new T.Vector3(X-.20,routeY,pc.z),new T.Vector3(X-.20,routeY,z),new T.Vector3(X-.20,1.7,z)];const len=wirePath(route,'#24d6ec',hdmiGroup);wirePath([supply.clone(),new T.Vector3(X-.08,3.15,z),new T.Vector3(X-.08,1.7,z)],'#ffad37',powerGroup);rows.push('TV '+(i+1)+' · '+gpu+' · route '+lengthText(len));}}else rows.push('LED mode: GPU-to-LED-processor design not specified. Switch to TVs for home-run diagram.');
wirePath([new T.Vector3(pc.x,.18,pc.z+.2),pc.clone()],'#ffad37',powerGroup);$('wiringSchedule').textContent=rows.join('\n');$('wiringSchedule').style.whiteSpace='pre-line';
const n=eastSystem==='tv'?eastCount:0;const tv=+ $('tvWatts').value||0,pcW=+$('pcWatts').value||0;$('wiringLoad').textContent=(n*tv+pcW).toLocaleString()+' W total allowance ('+n+' long-wall TVs + PC). Other room loads excluded.';equipmentStamp=[...equipment.position.toArray(),...equipment.scale.toArray(),equipment.rotation.y].join(',');}
$('hdmiRoutes').onchange=e=>{hdmiGroup.visible=e.target.checked;refreshWiring()};$('powerRoutes').onchange=e=>{powerGroup.visible=e.target.checked;refreshWiring()};
function drawCleanWiring(){clearGroup(cleanWiringGroup);shell.updateWorldMatrix(true,true);shell.traverse(o=>{if(!o.isMesh)return;const edges=new T.LineSegments(new T.EdgesGeometry(o.geometry),new T.LineBasicMaterial({color:'#81919a'}));edges.applyMatrix4(o.matrixWorld);cleanWiringGroup.add(edges)});box(.15,.15,.22,X-.08,3.15,0,new T.MeshBasicMaterial({color:'#ffad37'}),cleanWiringGroup);}
$('wiringPlan').onclick=()=>{$('planView').onclick();cleanWiringState=scene.children.map(o=>[o,o.visible]);for(const o of scene.children)o.visible=o===wiringGroup||o===cleanWiringGroup||o===eastScreens||o===northScreens;cleanWiringGroup.visible=true;scene.background.set('#e7edef');$('hdmiRoutes').checked=true;$('powerRoutes').checked=true;hdmiGroup.visible=powerGroup.visible=true;refreshWiring();drawCleanWiring();target.set(0,1,0);radius=19;theta=-.85;phi=.65};for(const id of ['tvWatts','pcWatts','hdmiPath'])$(id).onchange=refreshWiring;
try{$('hdmiPath').value=storage.getItem('snug-hdmi-path')||'top'}catch{$('hdmiPath').value='top'}$('hdmiPath').onchange=()=>{try{storage.setItem('snug-hdmi-path',$('hdmiPath').value)}catch{}refreshWiring()};
for(const id of ['eastCount','eastSystem','units']){const previous=$(id).onchange;$(id).onchange=e=>{previous?.(e);refreshWiring()}}refreshWiring();
function openPanel(name){if(name==='wiring')$('wiringPlan').onclick();else if(cleanWiringState){restoreCleanWiring();hdmiGroup.visible=powerGroup.visible=false;$('hdmiRoutes').checked=$('powerRoutes').checked=false;}document.querySelectorAll('[data-panel]').forEach(button=>{const active=button.dataset.panel===name;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;document.getElementById('panel-'+button.dataset.panel).hidden=!active});document.querySelector('aside').scrollTop=0;}
const tabs=[...document.querySelectorAll('[data-panel]')];tabs.forEach((button,i)=>{button.onclick=()=>openPanel(button.dataset.panel);button.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();openPanel(tabs[next].dataset.panel);tabs[next].focus()}});openPanel('views');
function animate(){requestAnimationFrame(animate);if((hdmiGroup.visible||powerGroup.visible)&&equipmentStamp!==[...equipment.position.toArray(),...equipment.scale.toArray(),equipment.rotation.y].join(','))refreshWiring();camera.position.set(target.x+radius*Math.sin(phi)*Math.sin(theta),target.y+radius*Math.cos(phi),target.z+radius*Math.sin(phi)*Math.cos(theta));camera.lookAt(target);renderer.render(mode==='detail'?detailScene:scene,camera)}animate();
